  "step1_summary": [
    "Chief complaint: Progressive anxiety over the past ≈2 months, worst in the mornings before work.",
    "Symptoms: • Onset ≈2 months, coinciding with a new, stressful job. • Daily dread of leaving the house/going to work. • Marked insomnia (goes to bed 22-23 h, sleeps ≈3–4 h, shallow). • Morning palpitations (irregular, last minutes–10 min, associated with fear of heart attack). • Low daytime energy, anhedonia, avoidance of friends/hobbies, reduced exercise. • No true panic attacks yet; no suicidal ideation.",
    "Aggravating factors: Thoughts of work, fear of being late.  Alleviating factors: none clearly stated.",
    "Past medical history: None mentioned.",
    "Medications/Allergies: None reported.",
    "Family history: Mother with a history of depression.",
    "Social history: Lives with parents. Alcohol: binges on Fri/Sat, occasional weekday wine; amount likely above recommended limits. Occasional smoker. No recreational drugs.",
    "Vital signs / exam: Not performed (tele-consultation).",
    "Labs/Imaging: None yet; GP plans basic bloods (unspecified)."
  ],
  "step2_vindicate": {
    "V": [
      "Paroxysmal supraventricular tachycardia (SVT) or atrial fibrillation: Could explain episodic palpitations and perceived irregular fast heart beat."
    ],
    "I": [
      "Subacute (viral) myocarditis: Can present with palpitations and fatigue, although no infective prodrome reported."
    ],
    "N": [
      "Pheochromocytoma: Catecholamine surges cause episodic palpitations, anxiety, insomnia."
    ],
    "D": [
      "Iron-deficiency anaemia: Causes fatigue, palpitations, low energy."
    ],
    "I2": [
      "Caffeine / alcohol-induced anxiety-palpitations: Regular alcohol binges and possible caffeine use could precipitate symptoms."
    ],
    "C": [
      "Mitral valve prolapse: Congenital/structural cause of palpitations often associated with anxiety."
    ],
    "A": [
      "Graves’ disease (autoimmune hyperthyroidism): Produces anxiety, insomnia, palpitations, weight change."
    ],
    "T": [
      "Work-related psychological stress (adjustment reaction): Emotional ‘trauma’ from hostile workplace triggering anxiety."
    ],
    "E": [
      "Generalised anxiety disorder / mixed anxiety-depressive disorder: Endocrine-metabolic ‘E’ category broadened here to psychiatric aetiology; fits chronic worry, somatic tension, sleep disturbance."
    ]
  },
